const $=id=>document.getElementById(id),today=new Intl.DateTimeFormat('en-CA',{timeZone:'Europe/London',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());let rowID=0,current=null,autoWeek={volume:12,longrun:4},example=false,selectedWeek=0;const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=s=>{s=Math.round(s);let h=Math.floor(s/3600),m=Math.floor(s%3600/60),sec=String(s%60).padStart(2,'0');return h?`${h}:${String(m).padStart(2,'0')}:${sec}`:`${m}:${sec}`},parseTime=t=>{const parts=t.trim().split(':').map(Number);if(!t.trim()||parts.some(n=>!Number.isFinite(n)||n<0)||parts.length>3)return NaN;return parts.length===1?parts[0]*60:parts.reduce((s,n)=>s*60+n,0)},dateText=s=>new Intl.DateTimeFormat('en-GB',{day:'numeric',month:'short',year:'numeric',timeZone:'UTC'}).format(new Date(s+'T12:00:00Z')),addDays=(s,n)=>new Date(StrideModel.stamp(s)+n*86400000).toISOString().slice(0,10),raceName=d=>d>10?'Half marathon':d+'K';
$('start').value=today;
function addRace(data={}){if(document.querySelectorAll('.race-entry').length>=5)return;const id=++rowID,div=document.createElement('div');div.className='race-entry';div.dataset.id=id;div.dataset.example=data.isExample?'1':'0';div.innerHTML=`<div class="race-heading"><b>Race result</b><button class="subtle remove-race" type="button" aria-label="Remove race result ${id}">Remove ×</button></div><label>Race name <span class="hint">optional</span><input class="r-name" maxlength="80" placeholder="e.g. local 10K" value="${esc(data.name||'')}"></label><div class="row"><label>Distance<select class="r-distance"><option value="5">5K</option><option value="10">10K</option><option value="21.0975">Half marathon</option></select></label><label>Race date<input class="r-date" type="date" value="${data.dateAssumed?'':data.date||''}"></label></div><div class="row"><label>Finish time <span class="hint">mm:ss or hh:mm:ss</span><input class="r-time" placeholder="55:00 or 00:55:00" value="${data.time||''}"></label><label>Result context<select class="r-context"><option value="yes">Comparable race effort</option><option value="no">Different conditions / effort</option></select></label></div>`;$('race-rows').append(div);div.querySelector('.r-distance').value=data.distance||10;div.querySelector('.r-context').value=data.context||'yes';div.querySelector('.remove-race').onclick=()=>{div.remove();updateRows();changed();suggest()};updateRows()}
function updateRows(){const rows=[...document.querySelectorAll('.race-entry')];rows.forEach((r,i)=>{r.querySelector('.race-heading b').textContent='RACE '+(i+1);r.querySelector('.remove-race').disabled=rows.length<=1});$('add-race').hidden=rows.length>=5}
function readRaces(){return[...document.querySelectorAll('.race-entry')].map(r=>({name:r.querySelector('.r-name').value,isExample:r.dataset.example==='1',distance:+r.querySelector('.r-distance').value,date:r.querySelector('.r-date').value,seconds:parseTime(r.querySelector('.r-time').value),comparable:r.querySelector('.r-context').value==='yes'}))}
function suggest(){const valid=readRaces().filter(r=>Number.isFinite(r.seconds)&&r.seconds>0).sort((a,b)=>(a.date||today).localeCompare(b.date||today));if(!valid.length)return;const r=valid.at(-1),pace=r.seconds/r.distance+75,easy=Math.max(2,Math.round(Math.max(20,Math.min(30,r.seconds/60*.4))*60/pace*2)/2),long=Math.max(2,Math.round(Math.max(30,Math.min(60,r.seconds/60*.65))*60/pace*2)/2);autoWeek={volume:easy*(+$('days').value-1)+long,longrun:long}}
function changed(){example=readRaces().some(r=>r.isExample);if(current){current=null;$('results').hidden=true;$('empty').hidden=false}}
$('runner-form').oninput=()=>{changed();suggest()};$('runner-form').onchange=()=>{changed();suggest()};$('add-race').onclick=()=>{addRace();changed();suggest()};
function read(){return{races:readRaces().filter(r=>Number.isFinite(r.seconds)&&r.seconds>0).map(r=>({...r,date:r.date||today,dateAssumed:!r.date,comparable:r.comparable&&!!r.date})),goal:+document.querySelector('[name=goal]:checked').value,customGoal:parseTime($('goal-time').value),days:+$('days').value,age:$('age').value?+$('age').value:null,gender:$('gender').value,reference:$('reference').value,experience:+$('experience').value,recovery:$('recovery').value,base:+$('experience').value>=8?'yes':'unknown',volume:autoWeek.volume,longrun:autoWeek.longrun,start:$('start').value||today,raceDate:$('race-date').value}}
$('runner-form').onsubmit=e=>{e.preventDefault();suggest();const p=read();if(!p.races.length){$('results').hidden=true;$('empty').hidden=false;return}selectedWeek=0;current={p,m:StrideModel.plan(p,today)};render();window.dispatchEvent(new CustomEvent('stride-plan',{detail:current}));$('result-panel').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'start'})};
function render(){const{p,m}=current;$('empty').hidden=true;$('results').hidden=false;if(m.blocked){$('results').innerHTML=`<div class="step-label"><span>02</span> RECOVERY COMES FIRST</div><h2>Give yourself room to return.</h2><p class="muted">You indicated pain or a return from injury. Race history can’t establish readiness for faster running, so we’re pausing the speed plan and race-time target.</p><p class="notice">Seek advice from a qualified clinician or physiotherapist for persistent pain or a return-to-running plan. Once you can run comfortably, update your recovery status and rebuild.</p><h3>Your recent results</h3>${historyTable(m)}${peerPanel(p,m)}<p class="reassess">A break doesn’t reveal your ceiling. Don’t use an old race result as a reason to push through pain.</p>`;return}const startWindow=addDays(p.start,m.weeks*7),endWindow=addDays(startWindow,28),check=addDays(p.start,28),chosen=p.raceDate?StrideModel.stamp(p.raceDate)<StrideModel.stamp(startWindow)?'Your chosen race is earlier than this preparation window. Treat it as a comfortable finish or choose a later target race.':StrideModel.stamp(p.raceDate)>StrideModel.stamp(endWindow)?'Your chosen race allows more time. Reassess rather than assuming extra weeks guarantee extra speed.':'Your chosen race falls inside the suggested planning window. Confirm readiness at your checkpoints.':'';const trend=m.state==='improving'?`${m.monthly.toFixed(1)}% faster / month observed`:m.state==='slowing'?`${Math.abs(Math.min(m.monthly,m.recentMonthly)).toFixed(1)}% slower / month recently`:m.state==='flat'?'Recent progress has levelled off':'Not enough comparable history';$('results').innerHTML=`<div class="step-label"><span>02</span> YOUR IMPROVEMENT PLAN</div>${example?'<span class="example-badge">EXAMPLE HISTORY · NOT YOUR RESULTS</span>':''}<div class="fitness-now"><div class="eyebrow">YOUR CURRENT FITNESS REFERENCE</div><h3>${fmt(m.base)} <small>for ${raceName(p.goal)}</small></h3><p>${m.latest.distance===p.goal?"Your latest entered result at this distance.":"An equivalent estimated from your latest entered result, not a result you have run."} ${m.age>120?"This result is older than 120 days; establish a fresh baseline before chasing a target.":"Treat this as a starting reference, not a guaranteed time today."}</p></div>${peerPanel(p,m)}<div class="result-hero"><div class="eyebrow">${raceName(p.goal).toUpperCase()} · YOUR NEXT GOAL</div><h2>${fmt(m.goalTarget)}</h2><p><b>${fmt(m.goalTarget/p.goal)} /km</b> · ${fmt(Math.abs(m.base-m.goalTarget))} ${m.goalTarget<m.base?'faster than':'slower than'} your current reference</p><p>${m.userGoal?'Your chosen goal. Adjust it anytime in the form.':'A modest faster ambition to train towards—not a prediction. Adjust the target finish time in the form to make it yours.'}</p><div class="result-meta"><div><b>${m.weeks} weeks</b><small>preparation horizon</small></div><div><b>${p.days} runs</b><small>per week</small></div></div></div><p class="notice">History-based uncertainty scenario: ${fmt(m.low)}–${fmt(m.high)}. A faster goal is an ambition, not a promise; use the check-ins to decide whether to keep it.</p><div class="explanation"><h3>Your progress, in perspective</h3><p class="trend-title">${trend}</p>${historyChart(m,p.goal)}<p class="label">Points show ${raceName(p.goal)} equivalents. Open circles are excluded from the trend. No projected straight line.</p>${historyTable(m)}<p class="muted">${m.enough?`${m.group.length} comparable ${raceName(m.group[0].distance)} results over ${Math.round(m.span)} days inform the trend.`:'Trend needs 3 comparable results at the same distance spanning at least 60 days, with a recent result.'} ${m.excluded?`${m.excluded} result(s) excluded for conditions or effort.`:''} ${m.age>120?'Your latest comparable result is over 120 days old; treat it as historical context.':''}</p><p class="notice">${m.mixed?'Some times are distance equivalents, not actual results at your goal distance. ':''}The range is a planning scenario, not a statistical confidence interval. A plateau doesn’t identify your body’s limit; recovery, training, conditions and consistency can all change the picture.</p></div><section class="race-window"><div class="eyebrow">A WINDOW TO PLAN AROUND</div><h3>${dateText(startWindow)} – ${dateText(endWindow)}</h3><p>Look for a ${raceName(p.goal)} in this window if training and recovery are going well. It is not a deadline for achieving the time.</p>${p.raceDate?`<p><b>Your race: ${dateText(p.raceDate)}</b><br>${chosen}</p>`:''}<p class="label">First check-in: ${dateText(check)}. Compare effort and recovery; don’t race a time trial every week.</p></section><div class="plan-tabs" role="group" aria-label="Plan sections"><button class="tab active" data-panel="training">Running</button><button class="tab" data-panel="strength">Strength & recovery</button><button class="tab" data-panel="fuel">Food & gels</button></div><div id="training" class="content-panel"><h3>How your weeks fit together</h3><div class="phase-list"><p><b>Establish →</b> ${m.prep?`First ${m.prep} weeks: easy running and a comfortable routine.`:'First 2 weeks: keep things easy and confirm recovery.'}</p><p><b>Build →</b> One long easy run each week. ${m.quality?'At most one controlled faster session weekly when the week is long enough, alternating tempo and intervals.':'Start with easy running while building a regular routine; revisit faster sessions as you recover comfortably.'}</p><p><b>Recover →</b> Every fourth week is lighter. Repeat a week whenever needed.</p><p><b>Taper →</b> Final 2 weeks: ease the volume and arrive rested.</p></div><div class="week-heading"><h3 id="week-heading"></h3><div class="week-nav"><button id="prev" aria-label="Previous training week">‹</button><button id="next" aria-label="Next training week">›</button></div></div><div id="week-content"></div><details class="workout-guide"><summary>Easy, tempo, intervals: what’s the difference?</summary><p><b>Easy:</b> relaxed full-sentence conversation. Most running belongs here. Estimated pace around ${fmt(m.easyPace)} /km is context only; effort leads.</p><p><b>Long run:</b> easy effort for longer, once per week. Build gradually; distance is not a weekly test.</p><p><b>Tempo:</b> controlled, comfortably hard effort (about 6/10). Speak in short phrases. Start with brief blocks rather than a whole hard run.</p><p><b>Intervals:</b> short controlled faster repetitions separated by easy jogging. They replace the tempo session on alternate weeks, not add to it.</p><p>Warm up and cool down. Don’t add speed and distance together. If tired or sore, replace a faster session with easy running or rest.</p></details></div><div id="strength" class="content-panel" hidden><h3>Strength that supports your running</h3><p class="muted">Work towards two short sessions a week, after easier runs rather than just before the long run. Start with one if strength training is new.</p><div class="exercise-grid"><div><b>Squat to chair</b><small>1–2 × 8–12 controlled repetitions</small></div><div><b>Calf raises</b><small>1–2 × 8–12, hold support if needed</small></div><div><b>Glute bridge / hip hinge</b><small>1–2 × 8–12, comfortable range</small></div><div><b>Step-ups</b><small>1–2 × 8 each side on a low stable step</small></div><div><b>Row or wall press-up</b><small>1–2 × 8–12 for upper-body strength</small></div><div><b>Dead bug</b><small>1–2 × 6 controlled repetitions each side</small></div></div><p class="reassess">Use a comfortable resistance, stop before form breaks, and increase gradually. These are starter examples, not a rehabilitation programme. <a href="https://www.nhs.uk/live-well/exercise/how-to-improve-strength-flexibility/" target="_blank" rel="noopener">NHS strength guidance ↗</a></p><h3>Recovery is part of the plan</h3><p class="muted">Keep at least one full rest day. Protect a regular sleep routine. Persistent fatigue, worsening performance, or pain calls for less load and reassessment.</p>${p.age?`<p class="notice">Age ${p.age}: we don’t apply an age-based speed ceiling. Let your response to training set the recovery spacing, and keep strength work gradual.</p>`:''}<p class="notice">${p.recovery==='tired'?'You reported difficult recovery. This plan starts lighter and defers quality work; don’t progress until fatigue improves.':'Progress only while your easy runs stay comfortable and you recover between sessions.'}</p></div><div id="fuel" class="content-panel" hidden>${fuelPanel(m)}</div><button class="primary download" id="download">Save my improvement plan <span>↓</span></button><p class="reassess">Reassess at weeks 4 and 8: comfortable mileage, recovery, and a comparable benchmark. If these aren’t improving, hold or revise the goal instead of chasing the forecast.</p>`;document.querySelectorAll('.tab').forEach(b=>b.onclick=()=>{document.querySelectorAll('.tab').forEach(x=>x.classList.toggle('active',x===b));document.querySelectorAll('.content-panel').forEach(x=>x.hidden=x.id!==b.dataset.panel)});$('prev').onclick=()=>{selectedWeek--;renderWeek()};$('next').onclick=()=>{selectedWeek++;renderWeek()};$('download').onclick=download;renderWeek()}
function historyTable(m){return`<div class="history-table">${m.sorted.map(r=>`<div><span>${esc(r.name||raceName(r.distance))}<small>${r.dateAssumed?'Date not supplied':dateText(r.date)} · ${raceName(r.distance)}${r.dateAssumed?' · not used for trend':r.comparable?'':' · different conditions'}</small></span><b>${fmt(r.seconds)}</b></div>`).join('')}</div>`}
function historyChart(m,goal){const vals=m.sorted.map(r=>r.seconds*Math.pow(goal/r.distance,1.06)),min=Math.min(...vals)*.97,max=Math.max(...vals)*1.03,start=StrideModel.stamp(m.sorted[0].date),span=Math.max(1,StrideModel.stamp(m.sorted.at(-1).date)-start);let dots=vals.map((v,i)=>{let x=20+(StrideModel.stamp(m.sorted[i].date)-start)/span*300,y=20+(v-min)/(max-min)*95;return`<circle cx="${x}" cy="${y}" r="5" stroke="#64824b" fill="${m.sorted[i].comparable?'#64824b':'#ebeee3'}"><title>${dateText(m.sorted[i].date)}: ${fmt(v)} equivalent</title></circle>`}).join('');return`<svg viewBox="0 0 340 135" class="history-chart" role="img" aria-label="Historical race-equivalent times. Higher points indicate faster times."><path d="M15 20H330 M15 65H330 M15 115H330" stroke="#d4ddc9" fill="none"/>${dots}</svg>`}
function renderWeek(){const{p,m}=current,w=StrideModel.weekPlan(p,m,selectedWeek);$('week-heading').textContent=`Week ${selectedWeek+1} · ${w.phase}`;$('prev').disabled=selectedWeek===0;$('next').disabled=selectedWeek===m.weeks-1;$('week-content').innerHTML=`<p class="muted">${dateText(addDays(p.start,selectedWeek*7))} · ${w.total.toFixed(1)} km · ${w.quality?'1 quality session':'all running easy'}</p>`+w.days.map((s,i)=>`<div class="session ${s.km?'':'rest'}"><span class="day">DAY ${i+1}<small>${new Intl.DateTimeFormat('en-GB',{weekday:'short',timeZone:'UTC'}).format(new Date(addDays(p.start,selectedWeek*7+i)+'T12:00:00Z')).toUpperCase()}</small></span><div><b>${s.title}${s.km?' · '+s.km.toFixed(1)+' km':''}</b><p>${s.detail}</p>${s.strength?'<p class="strength-note">+ Optional 15–20 min strength. Start with one session if new.</p>':''}</div></div>`).join('')+`<p class="reassess">${m.half?'For a half marathon, reassess long-run comfort before booking for a time. If endurance is still limited, extend the build or prioritise finishing. ':''}Distances are planning suggestions, not instructions to push through fatigue. Weeks can be repeated. These calendar slots start on your selected date; adjust around your routine.</p>`}
function fuelPanel(m){const minutes=m.base/60,long=m.startLong*m.easyPace/60;return`<h3>Fuel your training, not just race day</h3><p class="muted">Eat enough across the day. Include carbohydrate foods around training, protein-containing foods across meals, and a varied diet. Restricting food to chase a faster time can undermine recovery.</p><div class="fuel-card"><b>Before running</b><p>Try familiar, easy-to-digest carbohydrate foods: toast, oats, rice, or a banana. Allow time to digest. Practise your timing on training days.</p></div><div class="fuel-card"><b>During your ${raceName(m.half?21.0975:10)}</b><p>${minutes<60?'For a race under about an hour, gels are usually unnecessary. Focus on arriving fuelled and comfortable.':minutes<=150?'For exercise lasting 1–2.5 hours, general guidance is 30–60 g carbohydrate per hour. Practise on longer training runs before using this on race day.':'Your reference time exceeds 2.5 hours. Longer-event fuelling can differ; start by practising tolerance and seek individual advice from a sports dietitian rather than automatically increasing intake.'}</p></div><div class="fuel-card"><b>How gels fit in</b><p>Check the label: a gel’s carbohydrate content varies. At 25 g per gel, two per hour provide 50 g carbohydrate. Count sports drink and other food too. Follow water instructions on the packet and practise gut tolerance. Gels support fuel availability; they don’t create fitness.</p></div><div class="fuel-card"><b>After training</b><p>Have a meal or snack with carbohydrate and protein: yoghurt with cereal and fruit, a sandwich, or rice with beans, eggs, fish, or tofu. Replace fluids over time; needs vary with heat and sweat loss.</p></div><p class="notice">${long<60?'Your starting long run is under an hour, so it doesn’t call for routine gel use.':'Use longer runs to practise a familiar fuelling routine.'} Don’t experiment with new gels or supplements on race day.</p><p class="reassess">General guidance, not a prescribed diet. <a href="https://www.ausport.gov.au/ais/nutrition/supplements/group_a/sports-foods2/sports-drink/how-and-when-do-i-use-it" target="_blank" rel="noopener">AIS carbohydrate guidance ↗</a> · <a href="https://www.nswis.com.au/nswis-news/recovery-food-what-to-eat-and-when-to-eat-it/" target="_blank" rel="noopener">NSWIS recovery food ↗</a></p>`}
function download(){const{p,m}=current;let text=`STRIDE · IMPROVEMENT PLAN\n${raceName(p.goal)} scenario: ${fmt(m.low)}–${fmt(m.high)}\nNot a validated prediction or a lifetime ceiling.\nSuggested race window: ${dateText(addDays(p.start,m.weeks*7))}–${dateText(addDays(p.start,(m.weeks+4)*7))}\nCheck in at weeks 4 and 8. Repeat or reduce weeks if recovery is difficult.\n\nHISTORY\n`+m.sorted.map(r=>`${r.date} · ${r.name||raceName(r.distance)} · ${fmt(r.seconds)}${r.comparable?'':' (excluded from trend)'}`).join('\n')+'\n\n';for(let i=0;i<m.weeks;i++){let w=StrideModel.weekPlan(p,m,i);text+=`WEEK ${i+1} · ${w.phase} · ${w.total.toFixed(1)} km\n`+w.days.map((s,j)=>`${addDays(p.start,i*7+j)}: ${s.title}${s.km?' '+s.km+' km':''}. ${s.detail}${s.strength?' Optional short strength session.':''}`).join('\n')+'\n\n'}text+='STRENGTH: Start gradually, work towards two sessions/week: squats, calf raises, glute bridges, step-ups, rows/wall press-ups and dead bugs.\nFUEL: Regular meals with carbohydrate and protein. For 1–2.5 hour exercise, practise 30–60 g carbohydrate/hour; count all food and drinks. Gels vary; read labels. No new products on race day.\n';const url=URL.createObjectURL(new Blob([text],{type:'text/plain'})),a=document.createElement('a');a.href=url;a.download='stride-improvement-plan.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
$('example').onclick=()=>{$('race-rows').replaceChildren();[{distance:10,time:'00:58:00',ago:180},{distance:10,time:'00:55:30',ago:100},{distance:10,time:'00:55:15',ago:20}].forEach((r,i)=>addRace({...r,date:addDays(today,-r.ago),name:'Example 10K '+(i+1),isExample:true}));$('experience').value='8';$('recovery').value='well';$('days').value='4';$('age').value='';$('gender').value='';$('reference').value='';updateReference();$('race-date').value='';$('goal-time').value='';suggest();example=true;$('runner-form').requestSubmit()};$('about').onclick=()=>{$('method-details').open=true;$('method').scrollIntoView({behavior:'smooth'})};for(let i=0;i<3;i++)addRace();

$('save-history').onclick=()=>{const p=read();try{localStorage.setItem('stride-history-v1',JSON.stringify({...p,isExample:example,savedAt:today}));$('save-status').textContent='Saved on this device. Come back to add a result or update your fitness.'}catch{$('save-status').textContent='This browser could not save your history. You can still use and download your plan.'}};
$('clear-history').onclick=()=>{try{localStorage.removeItem('stride-history-v1');$('save-status').textContent='Saved history removed from this device. Current form stays here until you reload.'}catch{$('save-status').textContent='Saved history could not be removed by this browser.'}};
try{const saved=JSON.parse(localStorage.getItem('stride-history-v1'));if(saved&&Array.isArray(saved.races)&&saved.races.length>=1&&saved.races.length<=5){$('race-rows').replaceChildren();saved.races.forEach(r=>{const h=Math.floor(r.seconds/3600),m=Math.floor(r.seconds%3600/60),s=r.seconds%60;addRace({...r,time:[h,m,s].map(n=>String(n).padStart(2,'0')).join(':'),context:r.comparable?'yes':'no'})});for(const key of ['age','gender','reference','days','experience','recovery'])if(saved[key]!=null)$(key).value=saved[key];document.querySelector('[name=goal][value="'+saved.goal+'"]').checked=true;if(Number.isFinite(saved.customGoal)&&saved.customGoal>0)$('goal-time').value=fmt(saved.customGoal);example=!!saved.isExample;$('start').value=saved.start>=today?saved.start:today;$('race-date').value=saved.raceDate>=today?saved.raceDate:'';suggest();$('save-status').textContent='Your saved history is loaded. Update it and rebuild your plan.'}}catch{}

function updateReference(){const g=$('gender').value;$('reference-controls').hidden=g==='woman'||g==='man'}
$('gender').addEventListener('change',updateReference);updateReference();
function peerPanel(p,m){const category=p.gender==='woman'?'female':p.gender==='man'?'male':p.reference;
const prefix='<section class="peer-card"><div class="eyebrow">YOUR AGE & GENDER COMPARISON</div>';
if(!p.age||!category)return prefix+'<h3>Put your progress in context.</h3><p>Add your age and gender to compare with a published running-community benchmark. You can also choose an optional published reference category.</p></section>';
const actual=m.sorted.filter(r=>r.distance===p.goal&&r.comparable).at(-1),time=actual?actual.seconds:m.base,c=StrideBenchmarks.compare(p.age,category,p.goal,time);if(!c)return prefix+'<h3>No matching benchmark available.</h3><p>This comparison supports ages 18–90 and the source’s male/female categories. Your training plan still works without a comparison.</p></section>';
const delta=Math.abs(c.difference),direction=c.difference<0?'faster than':c.difference>0?'slower than':'equal to',difference=delta<1?'At the reference time':fmt(delta)+' '+direction+' the reference',estimated=!actual,identity=p.gender==='woman'||p.gender==='man'?'':'Selected reference · ';
return prefix+'<h3>'+difference+'</h3><p>'+identity+(category==='female'?'Female':'Male')+' reference · age '+p.age+' · '+raceName(p.goal)+'</p><div class="peer-times"><div><small>'+(estimated?'Your estimated equivalent':'Your race time')+'</small><b>'+fmt(time)+'</b></div><div><small>Published middle benchmark</small><b>'+fmt(c.benchmark)+'</b></div></div><p>'+(actual?'Compared result: '+dateText(actual.date)+'. Age uses your current input, not your age on race day.':'No comparable actual result at this goal distance: this comparison uses a race-equivalent estimate, so it is less reliable.')+'</p><p class="label">'+(c.interpolated?'Reference interpolated between published ages '+c.lowerAge+' and '+c.upperAge+'. ':'Published age '+p.age+' reference. ')+'Running Level’s intermediate standard is a community middle benchmark, not an average for everyone your age. No personal percentile is calculated.</p><a href="'+c.url+'" target="_blank" rel="noopener">View source & age table ↗</a><small class="peer-source">Checked '+c.checked+' · comparison only, not a limit or training target.</small></section>';
}
